import contextlib
import io
import unittest

from textkit import slug
from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class SlugifyTest(unittest.TestCase):
    def test_spec_examples(self):
        self.assertEqual(slug.slugify("Héllo, Wörld!"), "hello-world")
        self.assertEqual(slug.slugify("  C++ & Rust  "), "c-rust")
        self.assertEqual(slug.slugify("a b", sep="_"), "a_b")

    def test_accents_are_folded(self):
        self.assertEqual(slug.slugify("é"), "e")
        self.assertEqual(slug.slugify("Crème Brûlée"), "creme-brulee")

    def test_non_ascii_without_ascii_equivalent_is_dropped(self):
        self.assertEqual(slug.slugify("naïve 日本 café"), "naive-cafe")

    def test_lower_cases(self):
        self.assertEqual(slug.slugify("MiXeD Case"), "mixed-case")

    def test_runs_of_separators_collapse(self):
        self.assertEqual(slug.slugify("a   b--c__d"), "a-b-c-d")
        self.assertEqual(slug.slugify("a -.,;- b"), "a-b")

    def test_no_leading_or_trailing_sep(self):
        self.assertEqual(slug.slugify("--hi--"), "hi")
        self.assertEqual(slug.slugify("!hi!", sep="_"), "hi")

    def test_digits_are_kept(self):
        self.assertEqual(slug.slugify("Py 3.14 release"), "py-3-14-release")

    def test_custom_sep(self):
        self.assertEqual(slug.slugify("a b c", sep="."), "a.b.c")
        self.assertEqual(slug.slugify("a b", sep=""), "ab")

    def test_already_clean(self):
        self.assertEqual(slug.slugify("hello"), "hello")

    def test_nothing_left_raises(self):
        for text in ("!!!", "", "   ", "日本", "---"):
            with self.subTest(text=text), self.assertRaises(ValueError):
                slug.slugify(text)


class SlugCommandTest(unittest.TestCase):
    def test_accents_and_punctuation(self):
        self.assertEqual(run("slug", "Héllo, Wörld!"), (0, "hello-world\n", ""))

    def test_sep_option(self):
        self.assertEqual(run("slug", "a b", "--sep", "_"), (0, "a_b\n", ""))

    def test_nothing_left_exits_2(self):
        code, out, err = run("slug", "!!!")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_json_output(self):
        code, out, _ = run("--json", "slug", "a b")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["a-b"]', out)


if __name__ == "__main__":
    unittest.main()

