    return code, out.getvalue(), err.getvalue()


class TopWordsTest(unittest.TestCase):
    def test_counts_and_sorts_by_count(self):
        self.assertEqual(topwords.top_words("b a b c a b", 2), [("b", 3), ("a", 2)])

    def test_case_insensitive(self):
        self.assertEqual(topwords.top_words("The the THE cat", 1), [("the", 3)])

    def test_ties_broken_alphabetically(self):
        self.assertEqual(topwords.top_words("zeta alpha mid", 3),
                         [("alpha", 1), ("mid", 1), ("zeta", 1)])

    def test_apostrophe_splits_words(self):
        self.assertEqual(topwords.top_words("don't", 5), [("don", 1), ("t", 1)])

    def test_non_letters_separate_words(self):
        self.assertEqual(topwords.top_words("a1b2c, a-b a_b", 5),
                         [("a", 3), ("b", 3), ("c", 1)])

    def test_non_ascii_letters_are_separators(self):
        self.assertEqual(topwords.top_words("café café", 5), [("caf", 2)])

    def test_fewer_distinct_words_than_k(self):
        self.assertEqual(topwords.top_words("hi hi", 10), [("hi", 2)])

    def test_empty_text(self):
        self.assertEqual(topwords.top_words("", 3), [])
        self.assertEqual(topwords.top_words("123 !!!", 3), [])

    def test_k_below_one_raises(self):
        for k in (0, -1):
            with self.subTest(k=k), self.assertRaises(ValueError):
                topwords.top_words("a b", k)


